<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import SiteDialog from '@/features/management-shared/SiteDialog.vue'
import {getTeacherBankManagementApi,type QuestionImportPreview,type QuestionImportConfirmation} from '@/features/teacher-bank-management/api'
import {getTeacherStandaloneQuestionBankApi} from '@/features/teacher-bank-management/standalone-api'
import type {AdminRow} from './api'
const props=defineProps<{row?:AdminRow}>(),emit=defineEmits<{close:[];changed:[]}>(),api=getTeacherBankManagementApi(),standalone=getTeacherStandaloneQuestionBankApi(),file=ref<File>(),preview=ref<QuestionImportPreview>(),result=ref<QuestionImportConfirmation>(),selected=ref<string[]>([]),selectedGroups=ref<string[]>([]),busy=ref(false),error=ref('')
const groups=computed(()=>preview.value?.preview.groups||[]),rows=computed(()=>{const grouped=new Set(groups.value.flatMap(g=>g.member_row_ids));return (preview.value?.preview.rows||[]).filter(r=>!grouped.has(r.row_id))})
watch(()=>props.row,()=>{file.value=undefined;preview.value=undefined;result.value=undefined;selected.value=[];selectedGroups.value=[];error.value=''})
async function upload(){if(!file.value||!props.row)return;busy.value=true;error.value='';try{preview.value=props.row.course_id?await api.previewQuestionImport(props.row.course_id,Number(props.row.id),file.value):await standalone.previewQuestionImport(Number(props.row.id),file.value) as QuestionImportPreview;selected.value=rows.value.filter(r=>['ready','draft'].includes(r.classification)).map(r=>r.row_id);selectedGroups.value=groups.value.filter(g=>['ready','draft'].includes(g.classification)).map(g=>g.group_id)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function confirm(){if(!preview.value||!props.row)return;busy.value=true;error.value='';try{result.value=props.row.course_id?await api.confirmQuestionImport(props.row.course_id,Number(props.row.id),preview.value.preview_id,selected.value,selectedGroups.value):await standalone.confirmQuestionImport(Number(props.row.id),preview.value.preview_id,selected.value,selectedGroups.value) as QuestionImportConfirmation;emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const labels={ready:'可导入',draft:'保存为草稿',duplicate:'重复',invalid:'无效'}
</script>
<template><SiteDialog :open="Boolean(row)" title="导入题目" :subtitle="row?.name" wide @close="emit('close')"><div class="resource-import-steps"><span>01 上传文件</span><span>02 预览并选择</span><span>03 确认导入</span></div><div v-if="!result" class="form-grid"><label class="field">题目文件<input type="file" accept=".csv,.xlsx,.docx" @change="file=($event.target as HTMLInputElement).files?.[0];preview=undefined"></label><button :disabled="!file||busy" @click="upload">上传并预览</button><div v-if="preview" class="table-scroll"><table><thead><tr><th>选择</th><th>题目 / 题组</th><th>状态</th><th>校验说明</th></tr></thead><tbody><tr v-for="g in groups" :key="g.group_id"><td><input v-model="selectedGroups" type="checkbox" :value="g.group_id" :aria-label="'选择'+g.title" :disabled="!['ready','draft'].includes(g.classification)"></td><td><strong>{{ g.title }}</strong><small class="cell-sub">{{ g.item_count }} 个作答项 · {{ g.material }}</small></td><td>{{ labels[g.classification] }}</td><td>{{ g.errors.join('；') }}</td></tr><tr v-for="r in rows" :key="r.row_id"><td><input v-model="selected" type="checkbox" :value="r.row_id" :aria-label="'选择'+r.source_label" :disabled="!['ready','draft'].includes(r.classification)"></td><td><strong>{{ r.title || r.source_label }}</strong><small class="cell-sub">{{ r.text }}</small></td><td>{{ labels[r.classification] }}</td><td>{{ r.errors.join('；') }}</td></tr></tbody></table></div></div><div v-else role="status"><h3>导入已完成</h3><p>创建 {{ result.created }} 道题，跳过 {{ result.skipped ?? 0 }} 项。</p></div><p v-if="error" class="error-block" role="alert">{{ error }}</p><template #footer><button @click="emit('close')">关闭</button><button v-if="!result" class="primary" :disabled="busy||!preview||!selected.length&&!selectedGroups.length" @click="confirm">确认导入 {{ selected.length+selectedGroups.length }} 道完整题</button></template></SiteDialog></template>
